    [851] = {
        {
            id = 1075019,
            score = 52,
            author = "447186",
            text = "Completely changed in Cataclysm. You no longer have to run around killing kolkar in order to get him to spawn. After completing a pre-quest called  Flushing out Verog (http://cata.wowhead.com/quest=14072) where you collect 4 maps(called Centaur Intelligence) from any of the centaur camps you are offered this one. Travel to 51,78(new coords) which is the old Verog spawn point and look for a new kolkar called Wyneth. Kill him and Verog will spawn immediately down the hill a little way. He will then run at you and engage in combat.\n\nKill him and quest is done.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-07T03:51:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=851#comments:id=1075019",
        },
        {
            id = 13395,
            score = 27,
            author = "8579",
            text = "The command tent is at 53,40. Verog spawns slightly south of there at 52,41",
            date = "2006-12-11T10:50:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=851#comments:id=13395",
        },
        {
            id = 199144,
            score = 20,
            author = "Jamein",
            text = "Took me almost 45 minutes of killing centaurs to get him to spawn.\n\nI hate quests like this.",
            date = "2007-12-10T15:00:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=851#comments:id=199144",
        },
        {
            id = 2006652,
            score = 12,
            author = "Azoney",
            text = "Just kill Wyneth and Verog the Dervish will spawn.\nAt the tent on the hill 51,78",
            date = "2014-09-28T16:57:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=851#comments:id=2006652",
        },
        {
            id = 601405,
            score = 8,
            author = "62991",
            text = "The worst thing about this quest is not the sometimes ridiculous number of kills to summon him, but the fact that the summoned Verog isn't tagged to you.\nImagine spending more than 15 minutes killing centaur, then at last the message pops up. You run to the spawn point, only to find that some other %^&*!@# waited there and is killing him in front of your eyes without having lifted a finger to summon him.",
            date = "2009-02-09T06:54:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=851#comments:id=601405",
        },
    },
    [852] = {
        {
            id = 1986,
            score = 203,
            author = "1284",
            text = "Walks around the oasis clockwise. Go counterclockwise to find him.\n\nHe has 2 adds with him.",
            date = "2006-10-17T10:51:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=852#comments:id=1986",
        },
        {
            id = 654385,
            score = 22,
            author = "341082",
            text = "Solo-able as an 80 Afflic 'Lock.\n\nUpon seeing Hezrul and Co, my initial stratagem consisted of CoE'ing them individually, then following through with a rotation of Haunt, Corruption, Unstable Affliction, Immolate, Incinerate and Siphon Life.\nAnyone left standing would receive Curse of Doom.\n\nAlas, as plans o' mice and men are wont to go, I sneezed, clicked Hellfire, and watched in horror as the party incinerated in a puff of ash.\n\nNext time, I shall not be denied.",
            date = "2009-03-24T17:48:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=852#comments:id=654385",
        },
        {
            id = 1361740,
            score = 16,
            author = "difficult314",
            text = "walked all over at first didnt realize that some of cords given were BEFORE cataclysm.  but went to wailing cavern at 40,70 and they popped right up",
            date = "2011-03-08T22:32:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=852#comments:id=1361740",
        },
        {
            id = 67004,
            score = 13,
