    [4513] = {
        {
            id = 14432,
            score = 129,
            author = "9626",
            text = "The pure samples are from any of the oozes in Un'goro.",
            date = "2006-12-12T20:08:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=4513#comments:id=14432",
