    [6386] = {
        {
            id = 327887,
            score = 19,
            author = "Ametrine",
            text = "I wish there really would be a wedding of theirs we could attend.  I'm curious what such a ceremony might be like in the Orcish traditions.",
            date = "2008-07-16T15:49:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6386#comments:id=327887",
        },
        {
            id = 1038258,
            score = 13,
            author = "480749",
            text = "\" Nothing brings red to a lady's cheeks like a big, juicy steak! \"",
            date = "2010-05-13T17:16:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6386#comments:id=1038258",
        },
        {
            id = 1801674,
            score = 9,
            author = "Ivrandra",
            text = "I actually took a moment to read the letter and had a good laugh.\n\nDear Grimtak,\n\nThe steaks you sent are fine. Well marbled, thick sliced, and packed in boar fat. They're just how I like them. When I eat them later, I will think of you as I gnaw on the last bits of bone and gristle. I will close my eyes and see your strong scarred hands chopping and cutting...\n\nHah! That reminds me of when you had your accident and lost a finger... Oh, Grimtak! Thinking of that day makes me giggle like a little girl.\n\nYou're so cute when you're bleeding!\n\n-Gryshka",
            date = "2013-01-20T17:46:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6386#comments:id=1801674",
        },
        {
            id = 1077476,
            score = 5,
            author = "210999",
            text = "You can talk to the Orgrimmar Flight Master and get the quest completed without having to fly back to the Crossroads, if you have something else to do in Orgrimmar or Razor Hill and would prefer to head back later by other means.",
            date = "2010-07-10T13:36:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6386#comments:id=1077476",
        },
        {
            id = 2311433,
            score = 1,
            author = "Zerion123",
            text = "Return to Razor Hill https://youtu.be/_o59A7bTUh8",
            date = "2016-03-01T11:02:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6386#comments:id=2311433",
        },
    },
