    [6442] = {
        {
            id = 14591,
            score = 7,
            author = "8346",
            text = "You will find these Naga at the Zoram Strand in Ashenvale. They are between the levels of 17-20. If you are a Hunter, stop by this area and tame one of the crabs to get Claw Rank 3.\n\nThese nagas will always drop the Wrathtail Heads if you have the quest, so it is a very simple one to do. You will also find the quest \"Vorsa the Lasher\" http://www.wowhead.com/?quest=6641 here.\n\nIf you are horde, make sure to get the Flight Path at the Zoram Strand!",
            date = "2006-12-13T02:23:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6442#comments:id=14591",
        },
        {
            id = 346414,
            score = 4,
            author = "poobah",
            text = "As of Patch 2.4.3 Naga now have 100% drop rate of Wraithtail heads.",
            date = "2008-08-06T22:49:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6442#comments:id=346414",
        },
        {
            id = 124249,
            score = 1,
            author = "Nappa",
            text = "This quest has great spawn located right on the beach where the quest is given. Moreover it is very easy to kill Wrathtail enemies. The most they can do is take 50% of your armor or slow you down for 3 seconds, depending on who you are fighting. Great quest for some quick exp.",
            date = "2007-07-20T22:23:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6442#comments:id=124249",
        },
        {
            id = 698233,
            score = 1,
            author = "Raindance",
            text = "Grants Only Darkspear rep at 80 and revered.",
            date = "2009-04-29T02:24:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6442#comments:id=698233",
        },
        {
            id = 734870,
            score = 1,
            author = "Nikeleye",
            text = "Might be worth noting the caster (female) mobs seem to go down a lot quicker in melee than the male counterparts. Made for a very quick quest!",
            date = "2009-06-02T06:02:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6442#comments:id=734870",
        },
    },
