    [6827] = {
        {
            id = 11154,
            score = 24,
            author = "Serpent",
            text = "Mulverick is in the Dun Balder North Bunker.  He is lying near the flag on the ground.  You must interact with him to send him back to the Horde base.  If he makes it there successfully the Horde can turn in Stormpike Commander's Flesh to get his air unit up and running.",
