    [9420] = {
        {
            id = 21781,
            score = 45,
            author = "Flyv",
            text = "These spawns are heavily camped in busy times. But there's a trick to making more spawn. Sometimes you will see a Kaliri Nest on the ground. Click it and 1-2 Kaliri will spawn; sometimes hatchlings, sometimes matriarchs. I farmed a single spawn at 27,77 this way and got the quest done in about 15 minutes. Killed 22 birds to get 8 feathers.",
            date = "2007-01-19T20:44:03-06:00",
