    [9427] = {
        {
            id = 20814,
            score = 60,
            author = "9538",
            text = "North-west part of the Pools of Aggonar is a giant demonic skeleton. You can even see the skeleton on your mini-map. At the foot of the ribcage, while standing near poisoned waters, use your cleansing vial and Aggonar will appear. Defeat him and return to the Temple of Telhamat.\n\nI was standing at the front of his rib cage and on land when I did it.",
            date = "2007-01-16T12:23:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9427#comments:id=20814",
        },
        {
            id = 25534,
            score = 46,
            author = "5892",
            text = "40,30 there is a burned spot on the ground just at the end of the hammer hilt, stand there, right click the vial and move back!  mob spawns there and you have to kill it. I'd clear the surrounding mobs first though",
            date = "2007-01-27T06:38:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9427#comments:id=25534",
