    [9720] = {
        {
            id = 8221,
            score = 195,
            author = "6934",
            text = "Locations for the control panels are:\n-Umbrafen Steam Pump: 70, 80\n-Marshlight Steam Pump: 25, 43\n-Serpent Steam Pump: 62, 41\n-Lagoon Steam Pump: 63, 64\n\nRun up to the control panel, click the seed, and you're good to go.",
            date = "2006-12-07T03:31:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9720#comments:id=8221",
        },
        {
            id = 23023,
            score = 49,
            author = "Seks",
            text = "The Steam Pumps are the towers you see on the world map.",
            date = "2007-01-22T23:44:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9720#comments:id=23023",
        },
        {
            id = 33526,
            score = 43,
            author = "Fione",
            text = "Don't throw away your seeds when you have completed disabling all the towers. You will not be able to complete the quest without the seeds in your inventory.",
            date = "2007-02-10T09:32:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9720#comments:id=33526",
        },
        {
            id = 32189,
            score = 31,
            author = "Kathucka",
            text = "The control panel is hard to see.  Run under the center of the steam pump and use the seed.\n\nThe Naga call for help and aggro at unexpected times, so it's a good idea to clear a wide path before activating the seed.\n\nThe male naga will call for a nearby slave to assist them.  If you don't hit the slave, it will leave combat and run back to work after the naga dies.  Leave pets in passive mode to avoid hitting the slaves.",
            date = "2007-02-07T10:59:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9720#comments:id=32189",
        },
        {
            id = 111695,
            score = 23,
            author = "65842",
            text = "While you're doing this quest, make sure to kill the Steam Pump Overseers until they drop (9.2% chance)\n[Drain Schematics]\nhttp://www.wowhead.com/?item=24330\n\nWhich starts a quest of the same name.\nhttp://www.wowhead.com/?quest=9731\n\nWith really nice rewards for the simple amount of effort it requires.",
            date = "2007-06-27T05:53:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9720#comments:id=111695",
        },
    },
    [9724] = {
        {
