    [9752] = {
        {
            id = 190544,
            score = 17,
            author = "102462",
            text = "You also might want to pick up the Boglash quest. I did and happened to see him on the way back with the escort. I decided to pull him just to see if she would help and she did. Made killing him a complete joke. Way to get two quests done in a flash!",
            date = "2007-11-24T17:52:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9752#comments:id=190544",
        },
        {
            id = 962287,
            score = 17,
            author = "Torkle",
            text = "Best escort quest ever.\n\n1. She runs instead of walks.\n2. She takes a direct route to safety instead of meandering.\n3. She heals you and tries to help in combat.\n\nWhen compared to _ANY_ other escort quest, I look back on this one and think good thoughts about Kayra Longmane.",
            date = "2010-02-01T14:01:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9752#comments:id=962287",
        },
        {
            id = 21897,
            score = 16,
            author = "11505",
            text = "Shes inside one of the little tents in Umbrafen Village.\nVery easy solo quest. She´ll walk thought the village, once you leave the village she´ll run to the refuge (so its a quick trip). She has a \"huge\" agro area so be ready to fight stupid mobs around the road. She´ll stop about 02 times for new mobs that i´ll spawn cause of the quest.\nDid it solo as 61 very easy.",
            date = "2007-01-20T03:40:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9752#comments:id=21897",
        },
        {
            id = 23933,
            score = 15,
            author = "12831",
            text = "You can find Kayra in 83,85",
            date = "2007-01-24T18:22:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9752#comments:id=23933",
        },
        {
            id = 95855,
            score = 13,
            author = "Eversion",
            text = "This quest is really too easy, i had 5 mobs attacking me, started quest quickly, and she healed me 2600 each heal. You just can't fail this.",
            date = "2007-06-02T08:38:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9752#comments:id=95855",
        },
    },
