    [9805] = {
        {
            id = 13152,
            score = 130,
            author = "6934",
            text = "These huts are all in very close proximity of one another, if you found one you should be able to find them all.  To burn em down just run in and right click your Living Fire.  Tlocs are listed below:\n\nLarge hut - 72,50\nWestern hut - 70,51\nSouthern hut - 71,53\nEastern hut - 72,54",
            date = "2006-12-10T23:07:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9805#comments:id=13152",
        },
        {
            id = 25317,
            score = 114,
            author = "twunk",
            text = "I only had some trouble with setting the large hut on fire. The problem was that even though i was in the right hut, i wasn't standing in the right spot. You need to be on the first floor and have to stand somewhere in the middle to be able to set the fire.",
            date = "2007-01-26T19:48:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9805#comments:id=25317",
