    [9816] = {
        {
            id = 10128,
            score = 104,
            author = "6934",
            text = "Large rock's coords are 26,22.  If you find dancing murlocs entertaining, stick around to watch.",
            date = "2006-12-07T23:00:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9816#comments:id=10128",
        },
        {
            id = 132251,
            score = 81,
            author = "57456",
            text = "For everyone who has no idea how funny this really is, this quest is based off of an episode of loony toons. the name of the episode was \"Have you ever seen one of these\", where everyone thinks this guy`s crazy because he found a dancing frog that only dances when nobody else is arround, he tries to make a big show out of it and he lost everything his job and all his stuff, the murlocks also dance if you go see um where the quest giver is.",
            date = "2007-08-04T16:50:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9816#comments:id=132251",
        },
        {
            id = 284793,
            score = 63,
            author = "LumiyaSpellsong",
            text = "What a terribly cruel world we live in where one can be given a murloc cage literally \"filled with baby murlocs\" and we are not able to take even just ONE out to have and to hold and cuddle and snuggle until the end of time.  *sigh*  Oh Blizzard devs, how you taunt me so.  :(",
            date = "2008-05-08T20:17:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9816#comments:id=284793",
        },
        {
            id = 1034418,
            score = 44,
            author = "rbuffetta",
            text = "Hello, my baby\nHello, my honey\nHello, my ragtime gal\n\nSend me a kiss by wire\nBaby, my hearts on fire\n\nIf you refuse me\nHoney, you'll lose me\nThen you'll be left alone\n\nOh baby, telephone\nAnd tell me I'm your own\n\nHello, my baby\nHello, my honey\nHello, my ragtime gal\n\nSend me a kiss by wire\nBaby, my hearts on fire\n\nIf you refuse me\nHoney, you'll lose me\nThen you'll be left alone\n\nOh baby, telephone\nAnd tell me I'm your own",
            date = "2010-05-07T11:35:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9816#comments:id=1034418",
        },
