    [9857] = {
        {
            id = 12501,
            score = 20,
            author = "6934",
            text = "There's a small pond just southeast of Garadar that has these stags roaming around it.  You can circle this lake continuously until you get your 30 kills without stopping.  You'll also find the occassional Windroc and Clefthoof, which are quest mobs for quests that you can pick up at the Nesingwary camp as well.",
            date = "2006-12-09T23:55:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9857#comments:id=12501",
        },
        {
            id = 677200,
            score = 9,
            author = "300592",
            text = "As of patch 3.1 the number you need to kill has been reduced to 12. I would assume this holds true for all the others as well.",
