    [9875] = {
        {
            id = 77847,
            score = 47,
            author = "42324",
            text = "In the completion text, the name Lauranna suggests for the plant is actually your name followed by \"rium\" - if your name, for example, happens to be Bob, she'll name the plant \"Purple Leafed Bobrium\". Sooo... Neverdying honour! How's that for a quest reward. Your name will be passed down through history, and every time a new level 61 grinder tramples one of your flowers down, they'll remember you fondly. >_>",
            date = "2007-05-04T18:11:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9875#comments:id=77847",
        },
        {
            id = 20533,
            score = 15,
            author = "2250",
            text = "Does anyone know if you can do this quest more than once?",
            date = "2007-01-13T17:43:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9875#comments:id=20533",
        },
        {
            id = 989511,
