    [9879] = {
        {
            id = 51657,
            score = 80,
            author = "11636",
            text = "The captive will not offer the quest until the two brutes in the room with him have been killed.  If he happens to respawn when no brutes are present, it may look the like quest is bugged.  Simply wait for the brutes to respawn, kill them, and then the captive should offer the quest.\n\nKeep in mind also that your escort is only level 62, so keeping aggro off him is vital.",
            date = "2007-03-15T14:26:03-05:00",
