    [9882] = {
        {
            id = 18341,
            score = 63,
            author = "6513",
            text = "I've not seen this quest available from Gezhe, though I was Friendly with Consortium the first time I checked... perhaps it's not available above Neutral?",
            date = "2006-12-28T19:17:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9882#comments:id=18341",
        },
        {
            id = 12780,
            score = 37,
            author = "6934",
            text = "Head South to Oshu'gun and look for the large white crystal deposits. Around them you'll find ethereal raiders and arcanists. Both of these mobs can drop the crystals, but you can also loot them off the ground in these areas.\n\ntloc 34, 63 is an excellent example of one of these areas.\n\nThis quest becomes repeatable once completed.",
            date = "2006-12-10T13:49:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9882#comments:id=12780",
        },
        {
            id = 139335,
            score = 11,
            author = "79797",
            text = "Combine this quest with\nhttp://www.wowhead.com/?quest=9925\nhttp://www.wowhead.com/?quest=9900",
            date = "2007-08-17T04:21:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9882#comments:id=139335",
        },
        {
            id = 37047,
            score = 8,
            author = "Split",
            text = "if you get this at neutral, you can still turn in when u are friendly.",
            date = "2007-02-16T14:07:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9882#comments:id=37047",
        },
        {
            id = 764601,
            score = 7,
            author = "410692",
            text = "Definitely worth doing. Do it with :\nhttp://www.wowhead.com/?quest=9925\nhttp://www.wowhead.com/?quest=9900\n\nIt's much easier to pick them up rather than kill for them. Earns you experience and money while killing 3 birds with one stone. Plus, it's repeatable until 'Friendly' with The Consortium. As easy as Obsidian War Beads but much higher chance of getting it done. Definitely easier than Oshu'gun Powder Samples.\n\nAnother quest to do while killing VoidSpawns:\nhttp://www.wowhead.com/?quest=9914",
            date = "2009-07-01T12:11:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9882#comments:id=764601",
        },
    },
    [9883] = {
        {
            id = 32721,
            score = 63,
            author = "9388",
            text = "Stops at Friendly.  So don't go wasting time by farming the Ivory tusks as well as these fragments like I did.",
            date = "2007-02-08T15:01:06-06:00",
