    [9982] = {
        {
            id = 1967813,
            score = 26,
            author = "SnowyIVu",
            text = "For anyone trying to start this quest chain that hasn't done any questing in Nagrand, the quest Do My Eyes Deceive Me (http://wowhead.com/quest=9917) from the nearby Huntress Bintook is in fact a prerequisite.",
