    [10003] = {
        {
            id = 11874,
            score = 62,
            author = "6934",
            text = "You'll find her inside the large building within the Bonechewer Ruins(coords: 67, 53).  She's surrounded by 2-3 non elites, and she, herself, is non elite.  She is a caster-type mob and *can* be pulled solo either by means of counterspell or silencing.  If you don't have these abilities, try shooting her(dotting her, whatever enters you in combat from a ranged distance with her) and then simply using the wall near the entrance to line-of-sight pull her.\n\nSuggestion: Pair this quest up with: What Happens in Terokkar Stays in Terokkar (http://www.wowhead.com/?quest=10008 ) as both quest objectives/mobs are in the same confined area.",
            date = "2006-12-08T23:53:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10003#comments:id=11874",
        },
        {
            id = 22453,
            score = 52,
            author = "Boggus",
            text = "Don't forget to pickup the quest 'An Unseen Hand' from the same building she is found.\nThere is a small note near her that can easily be missed, that starts the quest.",
            date = "2007-01-21T15:29:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10003#comments:id=22453",
        },
        {
