    [10028] = {
        {
            id = 45912,
            score = 76,
            author = "13735",
            text = "You can easily detect if a vessel is a booby trap by hovering your mouse over it - real vessels change to a drastically lighter shade than the trapped ones. Since the real/fake state is predetermined, however, you may end up in a situation when you have to loot the booby traps just to get the real ones to spawn.",
