    [10099] = {
        {
            id = 937595,
            score = 112,
            author = "Basmothel",
            text = "Z'kral (http://www.wowhead.com/?npc=18974) has quite the long respawn time (over five minutes).  If you see someone else kill him or you do it yourself while you are doing the pre-requisite quest, (http://www.wowhead.com/?quest=10079) make a note to take a break before heading back into the mine or be prepared to wait around a small while.\n\nAlso, to many of the comments:  No one cares what you solo a normal level 62 mob with.",
            date = "2010-01-04T16:42:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10099#comments:id=937595",
        },
        {
