    [10101] = {
        {
            id = 22726,
            score = 167,
            author = "14002",
            text = "K'ure is at the end of the underground passage. The entrance is at 35, 67.",
            date = "2007-01-22T06:36:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10101#comments:id=22726",
