    [10106] = {
        {
            id = 47578,
            score = 39,
            author = "31333",
            text = "I think it should be noted that, at least for the Alliance side, you CANNOT already control the base to get credit. It must NOT belong to your faction to get the credit, despite the fact that you can stand there and let the timer count down. if you do this and your faction already is in control, you don't get credit.",
