    [10109] = {
        {
            id = 22569,
            score = 32,
            author = "13874",
            text = "You can get the elemental gases from any of the elemental wind stormers that are near the area. pretty regular drop rate. I killed 4 and collected the 3 gases.\n\nThe follow up is fun. You jump off a trampoline and land on a bird's nest. I had to erase the slow fall to actually land on the nest, otherwise i over shot it. Collect the egg and then the 66 (elite) bird swoops in. There was a mage doing the quest at the same time that I was. We teamed up and did just fine.",
            date = "2007-01-21T21:54:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10109#comments:id=22569",
        },
        {
            id = 29028,
            score = 16,
            author = "12881",
            text = "fall damage is a percentage so it doesn't matter how much health you have.",
            date = "2007-02-01T15:57:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10109#comments:id=29028",
        },
        {
            id = 238341,
            score = 4,
            author = "110798",
            text = "Also drops from Dust Howlers, alot North of The Ring of Trials (PvP Arena)\nCoords: 65,48",
            date = "2008-02-17T22:15:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10109#comments:id=238341",
        },
        {
            id = 449122,
            score = 3,
