    [10129] = {
        {
            id = 20780,
            score = 57,
            author = "11574",
            text = "When you accept the quest talk to a guy named Brack, tell him you're on a bombing mission. After that he flies you around 2 towers that look like they are from UD Strat.. ziggurats? Simply right click the bomb and left click under tower, rinse repeat. Done!",
            date = "2007-01-16T06:30:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10129#comments:id=20780",
        },
        {
            id = 2246049,
            score = 19,
            author = "NyaanCat",
            text = "Make sure you are not in any shape-shift forms before you talk to Wing Commander Brack (66.1,43.7) or else you wont be able to drop the bombs.",
            date = "2015-09-04T17:40:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10129#comments:id=2246049",
        },
        {
            id = 20963,
            score = 10,
            author = "bprater",
            text = "Right click on the bomb in your inventory as you start flight. Spin your camera around and look for the green crystal things ahead. You will be able to see where the bomb will land by hovering over the ground. Click as soon as it turns green. You can refly if you miss the first time.",
            date = "2007-01-17T03:29:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10129#comments:id=20963",
        },
        {
            id = 2230651,
            score = 9,
            author = "395728",
            text = "I just did this one on my druid.  Since I accepted the bombing run flight while in flight form, I could not use the bombs, since I was pacified.  I also could not shape-shift back to non-flight form.  I could, however, \"click off\" the flight form on my buff bar, and proceed as normal.",
            date = "2015-08-13T13:02:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10129#comments:id=2230651",
        },
        {
            id = 362306,
            score = 5,
            author = "venjur",
            text = "As of 8/25 this quest is broken in the beta WotLK version, you don't get credit for bombing the portals, and most the time it makes you fly off course and get stuck near the portals... =/",
            date = "2008-08-26T07:47:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10129#comments:id=362306",
        },
    },
