    [10160] = {
        {
            id = 535630,
            score = 9,
            author = "48141",
            text = "For those trying to achiveve the 80 quests in Hellfire for \"To Hellfire and Back\", this is essential.\nI was trying to complete this achivement but missed on set of crucial quests:\n\nChain 1:\nKnow your Enemy\nFel Orc Scavengers\nIll Omens\n\nLeads to\n\nChain 2:\nCursed Talismans\nWarlord of the Bleeding Hollow\nReturn to Honor Hold\n\nThis is handed in at Assistant Klatu\n\nThis leads to 2 more quests:\nDigging for Prayer Beads\nFel Spirits\n\nThese then lead on to:\n\nChain 3:\nThe Exorcism of Colonel Jules\nTrollbane is Looking for You\nDrill the Drillmaster",
            date = "2008-12-29T06:18:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10160#comments:id=535630",
        },
        {
            id = 263379,
