    [10162] = {
        {
            id = 13164,
            score = 47,
            author = "Sware",
            text = "One of the first quest you will be doing in Burning Crusade, the quest giver gives you the 'Area 52' bomb, with unlimited charges. Then you ask the guy to borrow a wyvern and you throw it off.\n\nYou are to hit the objectives with the bombs and has a pretty big area of effect.\n\nThe bomb deals 15,000 to 30,000 damage. The quest is also repeatable but no awards given after the first completion",
            date = "2006-12-10T23:18:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10162#comments:id=13164",
        },
        {
            id = 76462,
            score = 35,
            author = "Reversion",
            text = "This chain gives you your first really good set of Outlands armor (legs, chest, helmet, wpn). Each piece should out-perform most quest items from Azeroth. Very good chain to start with as it will provide some much-needed gear upgrades when fresh from the portal.",
            date = "2007-05-02T08:20:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10162#comments:id=76462",
        },
        {
            id = 22594,
