    [10168] = {
        {
            id = 37257,
            score = 135,
            author = "briyan",
            text = "Loot the mirror inside the Auchenai Crypts instance.\n\nTake it to Nagrand and talk to yellow Ancient Orc Ancestors to summon one Darkened Spirit elite, hits pretty hard.\n\nA good spot in Nagrand is around 36,66 just north of Oshu'gun. The yellow Ancient Orc Ancestors spawn repeatedly in this area so you'll never need to go searching.",
            date = "2007-02-16T21:46:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10168#comments:id=37257",
        },
        {
            id = 34621,
            score = 133,
            author = "19357",
            text = "I'd like to add that there is a mirror that spawns just behind the exarch so no need to run out and back in to get one...",
            date = "2007-02-12T10:43:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10168#comments:id=34621",
        },
        {
            id = 256905,
            score = 89,
            author = "128714",
            text = "Ok, if your like me and just ran out of the instance, and went to bed only to come on and find out that you need to go back into the instance to get one of these \"mirrors\".\n\nDon't Worry.\n\nWhen you enter the instance there should be a mirror at the end of the hallway and to the left a little near a pile of bones, you can just run up and get it.",
            date = "2008-03-21T09:51:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10168#comments:id=256905",
        },
        {
            id = 2585681,
            score = 48,
            author = "Zonarius",
            text = "Use this macro to quickly show the next https://www.wowhead.com/npc=18688 on the minimap:\n\n/target Ancient\n/focus",
            date = "2018-07-29T01:26:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10168#comments:id=2585681",
        },
        {
            id = 36035,
            score = 36,
            author = "23485",
            text = "Didn't see this mentioned before, so I'll throw it out there: The Darkened Spirits ARE fearable. Makes this a lot easier.",
            date = "2007-02-14T17:49:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10168#comments:id=36035",
        },
    },
    [10169] = {
        {
            id = 18798,
            score = 80,
            author = "2701",
            text = "Coords: 61,51",
            date = "2006-12-31T09:11:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10169#comments:id=18798",
        },
        {
            id = 261356,
            score = 34,
            author = "56975",
            text = "This quest appears to have been removed now that the soldiers occupying the inner ring of Shattrath are aligned with Shattered Sun Offensive (http://www.wowhead.com/?faction=1077).",
            date = "2008-03-27T17:47:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10169#comments:id=261356",
        },
        {
            id = 11256,
            score = 33,
            author = "6934",
            text = "This is outside near a ramp to the upper southeast bridge/exit on the terrace of light.  After 2-3 minutes they'll line up in formation and one will shoot another... with blanks.  You don't need to stay and watch if you don't want to.",
            date = "2006-12-08T14:34:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10169#comments:id=11256",
        },
        {
            id = 258548,
            score = 8,
            author = "6833",
            text = "Full dialogue =) Pretty amusing to watch!\n\nHarbinger Haronem says: Soup's on, men! Eat up. We've got a long day ahead.\nHarbinger Haronem says: Fall in men! It's time to drill!\nHarbinger Haronem says: Alright now, let's get those rifles sighted in...\nAldor Marksman says: ...at least we know my rifle is sighted properly.\nHarbinger Haronem says: Soldier...\nHarbinger Haronem says: You DO know that marksmen are issued blanks for practice drills, right?\nHarbinger Haronem says: Clearly, this group is not ready for weapons exercises.\nHarbinger Haronem says: Fall in for some marching practice! Let's see if we can manage to walk without suffering any casualties...\nHarbinger Haronem says: That was some pretty fancy prancin' ladies!\nHarbinger Haronem says: Now let's give shootin' another try...\nHarbinger Haronem says: Get into formation and get those guns sighted in!\nHarbinger Haronem says: Carefully now, we don't need any more mista-\nHarbinger Haronem says: Oh, that was cute...\nHarbinger Haronem says: We'll be marching all day if I see any more of that!\nHarbinger Haronem says: In fact, let's see some more of that fancy walkin'... Move it!\nHarbinger Haronem says: Again, very nice strutting ladies.\nHarbinger Haronem says: If we can't teach you to shoot, you'll have a career in the cantina to fall back on.\nHarbinger Haronem says: What's this? You've shifted into an incorrect formation!\nHarbinger Haronem says: You are only to use the staggered formation just before atta-\nHarbinger Haronem says: Enough messing around! There's a war going on here!\nHarbinger Haronem says: At ease, men.",
            date = "2008-03-24T08:43:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10169#comments:id=258548",
        },
        {
            id = 1083944,
            score = 8,
            author = "554624",
            text = "I guess this is the quest jimmy was talking about... http://www.youtube.com/watch?v=xeUhSjuhQYE&feature=related    :D",
            date = "2010-07-18T23:10:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10169#comments:id=1083944",
        },
    },
