    [10190] = {
        {
            id = 2356597,
            score = 164,
            author = "Brookelorren",
            text = "Quests like these have gotten a lot easier with the introduction of the https://www.wowhead.com/item=137663soft foam sword.  Just hit the creature with the sword, they lose most of their health but don't die, you can use the battery recharging blaster, then finish them off.\n\nI've been working on Loremaster and quests like these have been a pain, but this new toy is quite useful for these kinds of quest.",
            date = "2016-07-25T03:15:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10190#comments:id=2356597",
        },
        {
            id = 26973,
            score = 112,
            author = "15174",
            text = "You can find Phase Hunters at 28,51\nDPS them till you see the emote ''The Phase hunter is very weak'' and then use the [Battery Recharging Blaster].After that kill the hunter.",
            date = "2007-01-29T08:07:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10190#comments:id=26973",
        },
        {
            id = 19331,
            score = 68,
            author = "FryGuy",
            text = "To do this quest, bring the phase hunters down to ~30% and then use the battery charging blaster (provided) until the mob's name changes to \"drained phase hunter.\" It may not change the first time, so you won't get credit for the kill until you make it change name.",
            date = "2007-01-04T11:00:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10190#comments:id=19331",
        },
        {
            id = 2188681,
            score = 31,
            author = "CryCrimson",
            text = "As a lvl 100 bm hunter, https://www.wowhead.com/item=77589 worked very well.",
            date = "2015-05-29T09:01:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10190#comments:id=2188681",
        },
        {
            id = 22503,
            score = 23,
            author = "Eminence",
            text = "There's an emote that reads:\n\n\"Phase hunter is very weak\"\n\nThen you use the item (melee range btw!) You can also skin them! :) Watch out for mana drain.",
            date = "2007-01-21T18:09:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10190#comments:id=22503",
        },
    },
    [10191] = {
        {
            id = 38223,
            score = 34,
            author = "20065",
            text = "I'm not sure why it recommended 2 players.  Easy to solo as a 69 warrior (fury).\n\nCompleted\nhttp://www.wowhead.com/?quest=10300 and\nhttp://www.wowhead.com/?quest=10186\nat the same time.",
            date = "2007-02-18T15:48:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10191#comments:id=38223",
        },
        {
            id = 149401,
            score = 28,
            author = "50594",
            text = "Reference to Short Circut, who's main charcter went by Johnny 5.",
            date = "2007-09-05T11:41:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10191#comments:id=149401",
        },
        {
            id = 24850,
            score = 23,
            author = "Darsh",
            text = "No additional adds spawn, just the ghosts that are already in the city.\n\nHe will go pick up 3 items amidst the city.\n\nDespite the quest text, he can take a good beating, so don't be afraid to let him offtank.\n\nLargest group I ever had to deal with was 3, so with CC/him tanking, it was a cakewalk.\n\nRewarded 7g90s in addition to the experience.",
            date = "2007-01-26T05:23:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10191#comments:id=24850",
        },
        {
            id = 222181,
            score = 18,
            author = "Nivrax",
            text = "If anybody wondered... the name of this quest is much likely reference to the film Short Circuit (http://en.wikipedia.org/wiki/Short_Circuit) (Number V is Alive! - famous quotation from this film).",
            date = "2008-01-22T07:03:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10191#comments:id=222181",
        },
        {
            id = 29105,
            score = 12,
            author = "5883",
            text = "Mark V has loads of armor and health. Let him tank a few mobs and kill whatever one he starts attacking, move on to the next mob, and so on.\n\nWould take a good 5 mobs beating on him before you have to start to worry about his health getting low.\n\nHe also regens back to 100% immediately after exiting combat.",
            date = "2007-02-01T19:34:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10191#comments:id=29105",
        },
    },
    [10192] = {
        {
            id = 30954,
            score = 179,
            author = "18740",
            text = "Chapter 1 (http://www.wowhead.com/?item=28472): 58.6, 89.2\nChapter 2 (http://www.wowhead.com/?item=28473): 57.6, 89.6\nChapter 3 (http://www.wowhead.com/?item=28474): 58.8, 88.0\n\nI use Cartographer to get the fractional coordinates. It really helps in this area, as stuff is so close together.\n\nAlso while in this area, watch out for these mobs, each of them drops an item that starts a simple quest. Great exp if you do all 4!\n\nAbjurist Belmara (http://www.wowhead.com/?npc=19546)\nBattle-Mage Dathric (http://www.wowhead.com/?npc=19543)\nCohlien Frostweaver (http://www.wowhead.com/?npc=19545)\nConjurer Luminrath (http://www.wowhead.com/?npc=19544)",
            date = "2007-02-05T00:38:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10192#comments:id=30954",
        },
        {
            id = 25659,
            score = 129,
            author = "15629",
            text = "I found them all in one room houses. (you can see them, by looking in the door). There is 1 guard in each house but patrols walk by.\n\n58,87\n57,89\n58,89",
            date = "2007-01-27T11:09:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10192#comments:id=25659",
        },
        {
            id = 18917,
            score = 107,
            author = "5484",
            text = "Fun fact:\nKrasus is the name of one of the main characters from the Warcraft Books, in particular \"Day of the Dragon\", and the \"War of the Ancients Trilogy.\"\n\nHe's a dragon mage who is one of the leads of the Kirin Tor.",
            date = "2006-12-31T21:02:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10192#comments:id=18917",
        },
        {
            id = 22504,
            score = 71,
            author = "12909",
            text = "Chapter I: 59, 89\nChapter II: 58, 90\nChapter III: 59, 88",
            date = "2007-01-21T18:09:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10192#comments:id=22504",
        },
        {
