    [10198] = {
        {
            id = 33027,
            score = 40,
            author = "18990",
            text = "Co-ords are 48 84, not 78 84 as previously said.\n\nYou can mount with the costume on\nFollowup: http://www.wowhead.com/?quest=10330",
