    [10269] = {
        {
            id = 26225,
            score = 539,
            author = "DownD",
            text = "I had a problem getting this quest completed.\n\nMake sure that when you use the triangulation device you are not standing in the correct location to begin with (ie: 66., 33.8).  Stand a little outside the area and use it.  When the mark comes up, walk to it for the quest to complete, otherwise, you can be on the mark all you want, the quest will not show completed.\n\nHope this helps someone!",
            date = "2007-01-28T07:10:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10269#comments:id=26225",
        },
        {
            id = 5697,
            score = 108,
