    [10273] = {
        {
            id = 55446,
            score = 32,
            author = "36107",
            text = "Fact fans: one of his buddies at one point says: \"If you hear this whipser, you're dying\", which ofcourse is a line from Pink Floyd's \"The great gig in the sky\".",
            date = "2007-03-22T14:28:10-05:00",
