    [10318] = {
        {
            id = 27848,
            score = 78,
            author = "15629",
            text = "He is in the mine below the Manforge Ara. Entrance to the mine is 26,44. Go in the mine take your first right, then go straight till the end. he is behind two tents at the end of the tunnel (27,37)\n\ngl",
