    [10326] = {
        {
            id = 28744,
            score = 73,
            author = "11162",
            text = "Here is a list of items which you can hand in and up until which level (for aldor rep):\n\nDreadfang Venom Sac per 8 until Neutral (http://www.wowhead.com/?quest=10019)\n\nMark of Kil'jaeden per 10 until Honored (http://www.wowhead.com/?quest=10326)\n\nMark of Sargeras per 10 until Exalted (http://www.wowhead.com/?quest=10654)\n\nFel Armament per 1 until Exalted (http://www.wowhead.com/?quest=10421) You will also receive dust for which you can buy items.",
            date = "2007-02-01T05:38:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10326#comments:id=28744",
        },
        {
            id = 26045,
            score = 14,
            author = "12154",
            text = "Does this stop at a certain level of reputation?",
            date = "2007-01-27T23:19:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10326#comments:id=26045",
        },
        {
            id = 210420,
            score = 10,
            author = "Moogleson",
            text = "If your looking to farm these, goto Terrokar Forest->The Bone Wastes just north of Auchindoun. Farmed 70 in about 1 hour.",
            date = "2007-12-31T09:53:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10326#comments:id=210420",
        },
        {
            id = 257574,
            score = 6,
            author = "contraband",
            text = "Your aldor/scryer hand ins and quests also grant sha'tar rep up to 5999/6000 friendly, then it caps.\n\nthe exact vales can be found here: http://www.wowwiki.com/Sha'tar#Reputation",
            date = "2008-03-22T16:06:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10326#comments:id=257574",
        },
        {
            id = 1641176,
            score = 6,
            author = "cpopbdenny",
            text = "If you have marks of the Kil'jaeden, but have already reached Honored status with the Sha'tar, what can you do with them? (I have 55), the Aldor won't take them...",
            date = "2012-03-18T16:38:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10326#comments:id=1641176",
        },
    },
    [10327] = {
        {
            id = 22377,
            score = 5,
            author = "Curaris",
            text = "The following mobs had the most luck for me with dropping\n\nCabal Tomb-Raider (around 31,48)\nCabal Abjurist\009 (around 30, 53)\nCabal Skirmisher (around 38,56)\nCabal Spell-weaver (around 39,60)\n\nGoodluck with the quest",
            date = "2007-01-21T02:25:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10327#comments:id=22377",
        },
        {
            id = 61722,
            score = -2,
            author = "qhiiyr",
            text = "The rate of rep you receive does NOT change for turning in the marks in groups of ten. For example, if you turn in a single mark ten times, you'll get the same rep as if you turn in ten marks all together using the quest \"More Marks of Kil'jaeden\" (http://www.wowhead.com/?quest=10326). The ten-at-a-time quest is just there for convenience.\n\nThere IS a difference, though, and it's in the rep lost with the Scryers. Blizzard decided to round down for the rep loss, so for every ten marks you turn in individually, you'll lose 5 *less* rep with the Scryers than if you were to turn them in ten-at-a-time (doing the \"more marks\" quest brings you down 275 rep per 10 marks, while the \"single mark\" quest brings you down 27 per mark).\n\nNot much of an advantage unless you're planning on switching fractions at a later time and are willing to do 10x the clicking for 5 less rep per ten marks.",
            date = "2007-04-03T18:34:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10327#comments:id=61722",
        },
    },
