    [10382] = {
        {
            id = 20907,
            score = 20,
            author = "freak",
            text = "To get to Honor Point, first take the gryphon ride  to Shatter Point then talk to the gryphon master there. She'll take you to Honor Point.",
            date = "2007-01-16T22:54:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10382#comments:id=20907",
        },
        {
            id = 325899,
            score = 14,
            author = "Xhougnaamn",
            text = "This is a part of a 12 quest chain which you can start by talking to Force Commander Danath Trollbane (http://www.wowhead.com/?npc=16819) in Honor Hold. Here is the whole chain.\n\n¤ The Legion Reborn (http://www.wowhead.com/?quest=10141)\n¤ The Path of Anguish (http://www.wowhead.com/?quest=10142)\n¤ Expedition Point (http://www.wowhead.com/?quest=10143)\n¤ Disrupt Their Reinforcements (http://www.wowhead.com/?quest=10144)\n¤ Mission: The Murketh and Shaadraz Gateways (http://www.wowhead.com/?quest=10146)\n¤ Shatter Point (http://www.wowhead.com/?quest=10340)\n¤ Wing Commander Gryphongar (http://www.wowhead.com/?quest=10344)\n¤ Mission: The Abyssal Shelf (http://www.wowhead.com/?quest=10163)\n» Go to the Front (http://www.wowhead.com/?quest=10382)\n¤ Disruption - Forge Camp: Mageddon (http://www.wowhead.com/?quest=10394)\n¤ Enemy of my Enemy... (http://www.wowhead.com/?quest=10396)\n¤ Invasion Point: Annihilator (http://www.wowhead.com/?quest=10397)",
            date = "2008-07-13T18:55:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10382#comments:id=325899",
        },
        {
            id = 1662530,
            score = 10,
            author = "866741",
            text = "Just so its clear, you Speak to Gryphoneer Windbellow (http://www.wowhead.com/npc=20235) to get to Honour Point, not Gryphon Master Runetog Wildhammer (http://www.wowhead.com/npc=20234).",
            date = "2012-05-04T09:36:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10382#comments:id=1662530",
        },
        {
            id = 134950,
            score = 8,
            author = "Kastaje",
            text = "In order to get this quest you have to Complete Mission: The Abyssal Shelf.\nhttp://www.wowhead.com/?quest=10163",
            date = "2007-08-09T13:42:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10382#comments:id=134950",
        },
        {
            id = 377369,
