    [10395] = {
        {
            id = 21989,
            score = 8,
            author = "13354",
            text = "Dropped by Warbringer Arix'Amal at  53,26",
            date = "2007-01-20T09:20:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10395#comments:id=21989",
        },
        {
            id = 75429,
            score = 8,
            author = "Innervate",
            text = "Got the letter doing \"Go to the front\" chain (http://www.wowhead.com/?quest=10382). It drops from named NPC you have to kill for the last quest (http://www.wowhead.com/?quest=10397) and unlocks (can anyone confirmed this?) Overlord (elite: http://www.wowhead.com/?quest=10400) from Force Commander Danath Trollbane in Honor Hold.",
            date = "2007-04-30T11:04:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10395#comments:id=75429",
        },
        {
            id = 84302,
            score = 7,
            author = "46362",
            text = "I just got the letter that starts this quest.  It dropped from Warbringer Arix'Amal, as noted by others.\n\nI was not on any of the quests in that area and had not done any of them yet.  There does not apear to be any requirement.  Just go to the spot, kill him, loot.  I got it while at level 58.",
            date = "2007-05-16T22:40:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10395#comments:id=84302",
        },
        {
            id = 136789,
