    [10426] = {
        {
            id = 23326,
            score = 31,
            author = "Reanna",
            text = "It isn't necessary to zap the flowers immediately to mutate them, so you can save yourself the trouble of dealing with the enrage by just zapping them with the Energy Field Modulator when they're near death.",
            date = "2007-01-23T14:50:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10426#comments:id=23326",
        },
        {
            id = 66812,
            score = 23,
            author = "34144",
            text = "found some of them 42,38, and some around there",
            date = "2007-04-13T18:56:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10426#comments:id=66812",
        },
        {
            id = 30111,
            score = 20,
            author = "436",
            text = "The little guardians that are spawned can't move. So just move away from them and you don't have to kill them.",
            date = "2007-02-03T14:41:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10426#comments:id=30111",
        },
        {
            id = 34065,
            score = 8,
            author = "b1mmer",
            text = "Be carefull with the zapper. It zaps not only your target but all the flowers within its range. So if you have more then one flower nearby you are going to get ganked and they hit fast. Learned it the hard way :-/",
            date = "2007-02-11T12:10:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10426#comments:id=34065",
        },
        {
