    [10457] = {
        {
            id = 21950,
            score = 35,
            author = "12909",
            text = "The grove seedlings can be found just south of Sylvanaar.",
            date = "2007-01-20T06:30:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10457#comments:id=21950",
        },
        {
            id = 132103,
            score = 17,
            author = "67317",
            text = "It's a shame that Blizzard never thought to make these vital defenders that we summon actually assist you when you are attacked, or aggro anything around themsleves. Luckily, I discovered (much by accident) that they can be targeted and attacked, and derived much satisfaction out of killing every damned one I summoned. Take THAT, Rina Moonspring!",
            date = "2007-08-04T10:07:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10457#comments:id=132103",
        },
        {
            id = 27630,
            score = 15,
            author = "14618",
            text = "Confirmed.  Looks like the plants you have to gather in un'goro crater (the crops)",
            date = "2007-01-30T07:19:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10457#comments:id=27630",
        },
        {
            id = 74276,
            score = 14,
            author = "Jubjub",
            text = "You dont have to go very far. Just run out the gates of Sylvanaar and look by the bottom of trees for little roots. Very like the un'goro crater quest for the crops and very like the night elf starting place quest for the timberling sprouts.",
            date = "2007-04-28T06:44:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10457#comments:id=74276",
        },
        {
            id = 403023,
            score = 5,
