    [13883] = {
        {
            id = 1450272,
            score = 13,
            author = "721249",
            text = "I hate these \"sea bottom\" quests. Blizzard has a bunch of them.\n\nThere's no particular skill involved, just a long, boring search through murky waters for clams, or pieces of metal, or mossy footlockers.\n\nIt's quest like this that put the G in grind...",
            date = "2011-06-25T11:15:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13883#comments:id=1450272",
        },
        {
            id = 1394638,
            score = 8,
            author = "Ascendanzy",
            text = "Hugging the bottom will make them ten times easier to spot",
            date = "2011-04-19T03:16:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13883#comments:id=1394638",
        },
        {
            id = 1684742,
            score = 5,
            author = "Sooba",
            text = "The water is very deep, it takes you around 15 seconds to swim from the bottom to the surface, keep this in mind when you are running out of breath.",
            date = "2012-07-05T07:10:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13883#comments:id=1684742",
        },
        {
            id = 1819166,
            score = 5,
            author = "1099023",
            text = "Takes a while to swim all the way to the bottom and back up. Found a whole cluster around 7,31 though. Most of the pieces were found near hydra killing two birds with one stone.",
            date = "2013-02-28T07:31:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13883#comments:id=1819166",
        },
        {
            id = 1076832,
            score = 3,
            author = "447186",
            text = "Another gather type quest. This time you gather Sunken Scrap metal pieces from the ocean floor. The best way to tackle this quest is to go out along the piece of land that leads to the lighthouse. Start at 7,24 and travel west to 3,24. The scrap metal is strewn about along this line on the ocean floor. I found scraps at;\n8,25\n7,23 & 7,24\n6,24 & 6,25\n5,23\n4,25\n3,25\n\nIt's pretty deep and you will have to come up for breath a few times so you may want to bring a breathing potion.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-09T16:49:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13883#comments:id=1076832",
        },
    },
    [13884] = {
