    [13886] = {
        {
            id = 1224834,
            score = 50,
            author = "Laitarne",
            text = "I had the same problem, after trying it a couple times I think I narrowed it down to the quest being bugged so that if the periodic damage from Vortex Vengeance kills him you are not properly credited for the kill.\n\nMy final time, I slowly worked him to death with Sky Lightning after weakening him enough with Vortex Vengeance and was properly credited.",
            date = "2010-12-11T13:41:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13886#comments:id=1224834",
        },
        {
            id = 1200302,
            score = 14,
            author = "Whiterock",
            text = "Pre-quests: Hot Lava (http://www.wowhead.com/quest=13880) and Put Out The Fire (http://www.wowhead.com/quest=13884).",
            date = "2010-12-01T13:44:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13886#comments:id=1200302",
        },
        {
            id = 1393669,
            score = 6,
            author = "Gasparus",
            text = "I had the exact opposite happen.  Killed him five times with Sky Lightning with no DOT on him.  Then I tried letting the DOT kill him and got credit.  If it's bugged for you, might want to try it both ways.",
            date = "2011-04-17T16:47:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13886#comments:id=1393669",
        },
        {
            id = 1193246,
            score = 5,
            author = "622488",
            text = "Very easy quest.  After accepting the quest, talk to the vortex again and he will turn you into a cyclone and swap out your skill bar.  You will automatically fly up to the boss and, after defeating him, will be automatically flown back down.  In battle, throw the DoT spell on him (#2) and then hit on refresh, optherwise spamming the tiny damage spell (#1).  Damage text will scroll when you have the Lordly  Immolation on you and just immediately cleanse it with #3.  As long as you keep it cleansed (comes every 15 seconds or so) you will have no problems.",
            date = "2010-11-28T11:55:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13886#comments:id=1193246",
        },
        {
            id = 1708738,
            score = 5,
            author = "1028336",
            text = "First tried using both Sky Lightning and Vortex Vengence: No kill credit.\nNext tried using only Sky Lightning as final kill strike, no DoT: No kill credit.\nTried using only Sky Lightning throughout the fight: no kill credit.\nFinally tried using only Vortex Vengence throughout the fight: Kill Credit! Yay!",
            date = "2012-09-03T12:57:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13886#comments:id=1708738",
        },
    },
