    [13977] = {
        {
            id = 2180063,
            score = 3,
            author = "555344",
            text = "If you want to do any of the goblin's quests around Silverwind Refuge you first have to start with the quests at Hellscreams Watch. Specifically:  Tweedle's Dumb  (http://www.wowhead.com/quest=13936/tweedles-dumb)",
            date = "2015-05-07T20:05:51-05:00",
