    [13982] = {
        {
            id = 1394630,
            score = 11,
            author = "817567",
            text = "Be ready to fight as soon as you accept this quest, Kaliva (lv. 26) attacks just moments after.",
            date = "2011-04-19T03:01:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13982#comments:id=1394630",
        },
        {
            id = 2357461,
            score = 1,
            author = "miniwidge",
            text = "One thing I didn't see any reference to in the videos or these comments was that you have to pick up the \"Three Friends of the Forest\" quest from Benjari Edune at 17.9/49.5 (Ashenvale) to be sent here. Without that quest, these guys will not have anything to say to you (or sell to you). That first quest can be picked up at lvl 23. Race, professions, and rep with Darnassus don't seem to affect the quest at all (I tried it on a couple of toons).",
            date = "2016-07-26T17:22:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13982#comments:id=2357461",
        },
        {
            id = 2858459,
            score = 1,
            author = "Contay",
            text = "We must eat of her fel heart!\n\n\"Yanno, I think you could get the same effect from like... crushing it with a holy implement or-- okay, you're serious about eating it.\n\n\"Going over here, now.\n\n\"You three have fun with your glowing green eyes.\n\n\"Seeya.\"",
            date = "2018-12-13T12:10:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13982#comments:id=2858459",
        },
        {
            id = 3148836,
            score = 1,
            author = "dirch",
            text = "This quest leads to: Clear the Shrine (https://www.wowhead.com/quest=13985/clear-the-shrine)\n\nThere seem to be 2 Bolyun's in wowhead which adds to the confusion:\n\nThe Bolyun which is meet first and needs help with some lost friends (https://www.wowhead.com/npc=3698/bolyun)\nThe Bolyun which is returned to, after finding the friends, and wants to warn Big Baobob (https://www.wowhead.com/npc=34599/bolyun)",
            date = "2019-08-21T06:26:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13982#comments:id=3148836",
        },
