    [14435] = {
        {
            id = 1076063,
            score = 265,
            author = "533061",
            text = "Try not to bolt off when you pick up the quest, use the disguise right next to the quest giver and fireplace and the mage will teleport you to the quest area. Hoofing it to the quest area will not let you use the disguise.",
            date = "2010-07-08T12:19:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14435#comments:id=1076063",
        },
        {
            id = 1191489,
            score = 51,
            author = "Dradee",
            text = "This quest is hilarious. Seriously. Read the stuff you can say to Ungarl, read his responses too, and you will not regret it.",
            date = "2010-11-27T20:07:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14435#comments:id=1191489",
